    """Create a representative label for a cluster of category names.

    Uses the most common meaningful word(s) among members.
    The label should be representative of 70%+ of members.
    """
    all_words = Counter()
    for m in members:
        for w in word_set(m):
            if len(w) > 2:
                all_words[w] += 1

    if not all_words:
        return standardize_text(members[0]) if members else "General"

    # Find top word that appears in majority of members
    best_words = []
    for w, c in all_words.most_common(5):
        coverage = c / len(members)
        if coverage >= 0.5:
            best_words.append(w)
        if len(best_words) >= 2:
            break

    if not best_words:
        # Fall back to most common word
